package com.multitenanterp.payroll;
import org.springframework.http.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/payroll/runs/{year}/{month}/payslips") @PreAuthorize("@tenantAuthorization.hasAnyRole('SYSTEM_ADMIN','GROUP_ADMIN','COMPANY_ADMIN','PAYROLL_MANAGER','PAYROLL_EXECUTIVE')")
public class PayslipController{private final PayslipService service;public PayslipController(PayslipService service){this.service=service;}@GetMapping public List<Payslip> list(@PathVariable int year,@PathVariable int month){return service.list(year,month);}@PostMapping("/generate") @PreAuthorize("@tenantAuthorization.hasAnyRole('SYSTEM_ADMIN','GROUP_ADMIN','COMPANY_ADMIN','PAYROLL_MANAGER')") public List<Payslip> generate(@PathVariable int year,@PathVariable int month,Authentication authentication){return service.generate(year,month,authentication.getName());}@PostMapping("/release") @PreAuthorize("@tenantAuthorization.hasAnyRole('SYSTEM_ADMIN','GROUP_ADMIN','COMPANY_ADMIN','PAYROLL_MANAGER')") public List<Payslip> release(@PathVariable int year,@PathVariable int month,Authentication authentication){return service.release(year,month,authentication.getName());}@GetMapping("/{payslipId}/content") public ResponseEntity<org.springframework.core.io.Resource> download(@PathVariable int year,@PathVariable int month,@PathVariable UUID payslipId){var d=service.download(year,month,payslipId);return ResponseEntity.ok().contentType(MediaType.APPLICATION_PDF).contentLength(d.metadata().sizeBytes()).header(HttpHeaders.CONTENT_DISPOSITION,ContentDisposition.attachment().filename(d.metadata().fileName()).build().toString()).header("X-Content-SHA256",d.metadata().sha256()).body(d.resource());}}
